-- STA 132: Statistical Computing  (old code STA 172)
-- =============================================================================
-- 48 questions, every answer computed. Built from the STA 172 CA filler
-- (descriptive statistics, combined and corrected means, grouped-data quartiles,
-- index numbers, regression, correlation, trend analysis and hypothesis
-- testing). Where the printed filler answer was missing or inconsistent, the
-- answer was re-derived: the sample-variance item (the printed data give 86.55,
-- not any listed option) is rewritten as a formula question plus a computed
-- value; "median of 6, 9, x, x+1, 12, 16" and the 'x and y in the accidents
-- table' item were dropped because their options or data were incomplete.
-- Replaces the placeholder subject 'sta-172-coming-soon' (renamed STA 132).
-- ASSUMPTIONS: 100 Level, second semester, 2 units; same faculties as STA 122.
-- =============================================================================

delete from public.cbt_questions where subject_id in ('sta-172-coming-soon', 'sta-132-statistical-computing');

