  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean weight of 150 students is 60 kg. Boys average 70 kg and girls 55 kg. The number of girls and boys respectively is:', '["100 and 50","100 and 70","70 and 50","50 and 100"]'::jsonb, 0, 'Let boys $= b$: $70b + 55(150 - b) = 9000$, so $15b = 750$ and $b = 50$; girls $= 100$.', 'Combined Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In a class of 50 students, 10 failed with an average mark of 2.5. The total marks of the class were 281. The average mark of those who passed is:', '["5.4","6.4","7.2","3.8"]'::jsonb, 1, 'Marks of those who passed $= 281 - 25 = 256$; $256/40 = 6.4$.', 'Combined Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Given two mutually exclusive hypotheses, the one the experimenter expects to reject is the:', '["alternative hypothesis","composite hypothesis","null hypothesis","simple hypothesis"]'::jsonb, 2, 'The null hypothesis is stated in order to be tested and, usually, rejected.', 'Hypothesis Testing Concepts', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A researcher studies the IQ of all students at a university. The entire body of students is an example of a:', '["parameter","statistic","sample","population"]'::jsonb, 3, 'A population is the whole group of interest.', 'Basic Concepts', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the data X: 15, 14, 13, 12, 11 with frequencies 1, 6, 12, 8, 2, the mean is:', '["12.86","13.00","12.50","13.40"]'::jsonb, 0, '$\bar{x} = \dfrac{\sum fx}{\sum f} = \dfrac{374}{29} = 12.90$.', 'Measures of Central Tendency', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same frequency data, the median is:', '["12","13","14","12.5"]'::jsonb, 1, 'With 29 values the 15th is the median; cumulative frequencies are 2, 10, 22, ...; the 15th value is 13.', 'Measures of Central Tendency', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same frequency data, the mode is:', '["14","12","13","15"]'::jsonb, 2, 'The value 13 has the highest frequency (12).', 'Measures of Central Tendency', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Data arranged in ascending or descending order of magnitude is called:', '["grouped data","a discrete frequency distribution","a histogram","an array"]'::jsonb, 3, 'An array is an ordered list of raw values.', 'Basic Concepts', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean of 100 items is 30. Two items were wrongly taken as 32 and 12 instead of 23 and 11. The correct mean is:', '["29.9","30.0","30.1","29.0"]'::jsonb, 0, 'Correct sum $= 3000 - (32 + 12) + (23 + 11) = 2990$.', 'Corrected Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean age of a combined group of men and women is 30. If the men average 32 and the women 27, the percentage of men and women is:', '["70% and 40%","60% and 40%","60% and 60%","50% and 30%"]'::jsonb, 1, 'Let the proportion of men be $p$: $32p + 27(1 - p) = 30$, so $p = 0.6$.', 'Combined Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The weights (kg) of 15 students are 31, 35, 27, 29, 32, 43, 37, 41, 34, 28, 36, 44, 45, 42, 30. The median is:', '["34","36","35","37"]'::jsonb, 2, 'Sorted: 27, 28, 29, 30, 31, 32, 34, 35, 36, 37, 41, 42, 43, 44, 45. The 8th value is 35.', 'Measures of Central Tendency', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The median is the same as the:', '["first quartile","third quartile","first decile","second quartile"]'::jsonb, 3, 'The median is also the 2nd quartile, 5th decile and 50th percentile.', 'Quartiles and Percentiles', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The fiftieth percentile, the fifth decile and the second quartile of a distribution are all equal to the:', '["median","mean","mode","variance"]'::jsonb, 0, 'All three mark the middle of the ordered data.', 'Quartiles and Percentiles', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If the arithmetic mean of 20 observations is 12, their sum is:', '["32","240","8","1.667"]'::jsonb, 1, 'Sum $= n\bar{x} = 20 \times 12 = 240$.', 'Measures of Central Tendency', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The correlation coefficient is a:', '["quantity measured in the units of $x$","qualitative measure","unitless quantity","measure of central tendency"]'::jsonb, 2, '$r$ has no units and lies between $-1$ and $+1$.', 'Correlation Coefficient', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Given $\bar{X} = 110$, $\mu = 100$ and $\sigma_{\bar{x}} = 5$, the value of $z$ is:', '["4.000","2.500","0.500","2.000"]'::jsonb, 3, '$z = (110 - 100)/5 = 2$.', 'Standardised Scores', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Given $\sum X = 83$, $\sum X^{2} = 1467$ and $n = 8$, which formula gives the sample variance?', '["$S^{2} = \\dfrac{\\sum X^{2} - (\\sum X)^{2}/n}{n - 1}$","$S^{2} = \\dfrac{\\sum X^{2}}{n}$","$S^{2} = \\dfrac{\\sum X}{n - 1}$","$S^{2} = \\left(\\dfrac{\\sum X}{n}\\right)^{2}$"]'::jsonb, 0, 'The computing formula subtracts $(\sum X)^{2}/n$ and divides by $n - 1$.', 'Measures of Dispersion', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Using that formula with $\sum X = 83$, $\sum X^{2} = 1467$ and $n = 8$, the sample variance is:', '["10.375","86.554","183.375","86.550"]'::jsonb, 1, '$S^{2} = (1467 - 861.125)/7 = 605.875/7 = 86.554$.', 'Measures of Dispersion', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean birth weight of 100 infants was 32.02 g. It was later found that a weight of 57 had been read as 27. The correct mean is:', '["32.02","31.72","32.32","32.92"]'::jsonb, 2, 'Correct sum $= 3202 + 30 = 3232$, so the mean is 32.32.', 'Corrected Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Rice cost N700 (4 bags) and gas N150 (4 kg) in 1990; in 2000 rice cost N950 (3 bags) and gas N220 (6 kg). The aggregate price index for 2000 (base 1990) is:', '["120.560","130.467","300.324","137.647"]'::jsonb, 3, 'Aggregate price index $= \dfrac{\sum p_{1}}{\sum p_{0}} \times 100 = \dfrac{1170}{850} \times 100 = 137.647$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same data, the aggregate quantity index for 2000 (base 1990) is:', '["112.5","114.5","145.5","432.5"]'::jsonb, 0, '$\dfrac{\sum q_{1}}{\sum q_{0}} \times 100 = \dfrac{9}{8} \times 100 = 112.5$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The average weight of 40 boys and 20 girls is 50 kg. If the boys average 54 kg, the average weight of the girls is:', '["46 kg","42 kg","50 kg","54 kg"]'::jsonb, 1, 'Total $= 60 \times 50 = 3000$; boys $= 40 \times 54 = 2160$; girls $= 840/20 = 42$.', 'Combined Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A grouped distribution has class intervals 250-275 up to 425-450 with frequencies 15, 51, 240, 681, 978, 744, 264, 27 (total 3,000). The median is approximately:', '["350.00","362.50","363.11","375.00"]'::jsonb, 2, 'The median class is 350-375 (cumulative frequency before it: 987). Median $= 350 + \dfrac{1500 - 987}{978}(25) = 363.11$.', 'Grouped Data', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same distribution, the first quartile $Q_{1}$ is approximately:', '["325.00","337.50","350.00","341.30"]'::jsonb, 3, '$Q_1$ class is 325-350 (cumulative frequency before it: 306). $Q_1 = 325 + \dfrac{750 - 306}{681}(25) = 341.30$.', 'Grouped Data', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same distribution, the third quartile $Q_{3}$ is approximately:', '["384.58","375.00","387.50","400.00"]'::jsonb, 0, '$Q_3$ class is 375-400 (cumulative frequency before it: 1,965). $Q_3 = 375 + \dfrac{2250 - 1965}{744}(25) = 384.58$.', 'Grouped Data', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which of these can be read from a histogram?', '["the mean","the mode","the median","the variance"]'::jsonb, 1, 'The tallest bar marks the modal class.', 'Graphical Methods', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which of these can be read from an ogive?', '["the mean","the mode","the median","the variance"]'::jsonb, 2, 'The ogive is the cumulative frequency curve; the median is read at half the total frequency.', 'Graphical Methods', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The least squares method used in regression analysis is a:', '["maximisation technique","subjective method","graphical measure only","minimisation technique"]'::jsonb, 3, 'It minimises the sum of squared residuals.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Given $\bar{X} = 53$, $\mu = 50$, $\sigma = 9$ and $n = 20$, test $H_{0}: \mu = 50$ against $H_{1}: \mu > 50$ at $\alpha = 0.01$. The value of $Z$ is:', '["1.49","0.33","3.00","1.00"]'::jsonb, 0, '$Z = \dfrac{3}{9/\sqrt{20}} = 1.49$.', 'Test of One Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For that test, with critical value $Z_{0.01} = 2.33$, the decision is:', '["reject $H_{0}$, since $1.49 > 1$","accept $H_{0}$, since $1.49 < 2.33$","reject $H_{0}$, since $1.49 < 2.33$","no decision"]'::jsonb, 1, 'The statistic is inside the acceptance region.', 'Test of One Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The average rainfall in a city from Monday to Saturday is 0.3 inch. With heavy rain on Sunday, the average for the week rises to 0.5 inch. The rainfall on Sunday was:', '["0.2 inch","1.0 inch","1.7 inches","2.5 inches"]'::jsonb, 2, 'Week total $= 7 \times 0.5 = 3.5$; Monday to Saturday $= 6 \times 0.3 = 1.8$; Sunday $= 1.7$.', 'Corrected Mean', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Four commodities were consumed in quantities 20, 35, 10, 45 (2006) and 16, 38, 9, 50 (2007) at unit prices 1.2, 2.1, 3.0, 0.8 (2006) and 2.0, 2.4, 4.1, 1.2 (2007). Laspeyres price index for 2007 (base 2006) is:', '["123.54","144.50","289.50","133.94"]'::jsonb, 3, 'Laspeyres $= \dfrac{\sum p_{1}q_{0}}{\sum p_{0}q_{0}} \times 100 = \dfrac{219}{163.5} \times 100 = 133.94$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same data, the Paasche price index is:', '["132.59","123.94","134.50","144.50"]'::jsonb, 0, 'Paasche $= \dfrac{\sum p_{1}q_{1}}{\sum p_{0}q_{1}} \times 100 = \dfrac{220.1}{166} \times 100 = 132.59$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same data, Fisher''s ideal index is:', '["112.59","133.27","124.50","134.50"]'::jsonb, 1, 'Fisher $= \sqrt{L \times P} = \sqrt{133.94 \times 132.59} = 133.26$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Fisher''s ideal index number is the:', '["arithmetic mean of the Laspeyres and Paasche indices","difference between Laspeyres and Paasche","geometric mean of the Laspeyres and Paasche indices","Laspeyres index divided by Paasche index"]'::jsonb, 2, 'Fisher''s index $= \sqrt{L \times P}$.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The Laspeyres index uses weights from the:', '["current year","average of both years","previous month only","base year"]'::jsonb, 3, 'Laspeyres weights prices by base-year quantities; Paasche uses current-year quantities.', 'Index Numbers', false, 'second', 2),
  ('sta-132-statistical-computing', 'STA 132: Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The average of the marks of 36 students was 52, but a score of 64 was misread as 46. The correct mean is:', '["52.5","51.5","50.4","55.9"]'::jsonb, 0, 'Correct sum $= 1872 + 18 = 1890$; $1890/36 = 52.5$.', 'Corrected Mean', false, 'second', 2),
